// Every page: nav bar menus, light/dark, recipe search, the Ctrl/Cmd+K command
// palette, filter chips, fade-up on scroll, card tilt and offline support.
// The recipe index comes from search-index.js (generated by build.py) as a plain
// script, so all of this also works when the site is opened straight from disk.
(function () {
  var MAX_RESULTS = 8;
  var nav = document.querySelector(".site-nav");
  if (!nav) return;
  // Menus only collapse once JS is here to open them again (see style.css).
  nav.classList.add("js");
  var root = nav.getAttribute("data-root") || "";
  var index = window.FIELD_KITCHEN_INDEX || [];
  var calm = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  function stored(key, fallback) {
    try { var v = localStorage.getItem(key); return v ? JSON.parse(v) : fallback; } catch (e) { return fallback; }
  }

  // ---- Menus ----
  var menuToggle = nav.querySelector(".menu-toggle");
  var cuisineMenu = nav.querySelector(".cuisine-menu");
  var cuisineToggle = nav.querySelector(".cuisine-toggle");
  var input = nav.querySelector(".search input");
  var list = nav.querySelector(".search-results");

  function setMenu(open) {
    nav.classList.toggle("menu-open", open);
    menuToggle.setAttribute("aria-expanded", String(open));
  }
  function setCuisines(open) {
    cuisineMenu.classList.toggle("open", open);
    cuisineToggle.setAttribute("aria-expanded", String(open));
  }
  menuToggle.addEventListener("click", function () { setMenu(!nav.classList.contains("menu-open")); });
  cuisineToggle.addEventListener("click", function () { setCuisines(!cuisineMenu.classList.contains("open")); });
  document.addEventListener("click", function (e) {
    if (!cuisineMenu.contains(e.target)) setCuisines(false);
    if (!nav.contains(e.target)) setMenu(false);
    if (!input.form.contains(e.target)) list.hidden = true;
  });

  function onScroll() { nav.classList.toggle("scrolled", window.scrollY > 4); }
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  // ---- Shopping list count on the basket ----
  var badge = nav.querySelector(".list-count");
  function updateBadge() {
    var n = stored("fk-list", []).length;
    badge.textContent = n;
    badge.hidden = n === 0;
  }
  updateBadge();
  window.addEventListener("storage", updateBadge);
  document.addEventListener("fk-list-changed", updateBadge);

  // ---- Light / dark ----
  // The choice is a per-browser convenience; without storage it lasts for the visit.
  function toggleTheme() {
    var html = document.documentElement;
    var dark = html.getAttribute("data-theme") === "dark" ||
      (!html.getAttribute("data-theme") && window.matchMedia("(prefers-color-scheme: dark)").matches);
    var next = dark ? "light" : "dark";
    html.setAttribute("data-theme", next);
    try { localStorage.setItem("fk-theme", next); } catch (e) { /* storage blocked */ }
  }
  nav.querySelector(".theme-toggle").addEventListener("click", toggleTheme);

  // ---- Search ----
  function fold(text) {
    return text.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");
  }
  function search(query, limit) {
    var terms = fold(query).split(/\s+/).filter(Boolean);
    if (!terms.length) return [];
    return index
      .map(function (r) {
        var title = fold(r.title);
        var hay = title + " " + fold(r.cuisine + " " + r.category + " " + r.text);
        if (!terms.every(function (t) { return hay.indexOf(t) !== -1; })) return null;
        var score = terms.filter(function (t) { return title.indexOf(t) !== -1; }).length;
        return { r: r, score: score };
      })
      .filter(Boolean)
      .sort(function (a, b) { return b.score - a.score || a.r.title.localeCompare(b.r.title); })
      .slice(0, limit || MAX_RESULTS)
      .map(function (m) { return m.r; });
  }
  window.FieldKitchenSearch = search;

  function show(results, query) {
    list.textContent = "";
    if (!query.trim()) { list.hidden = true; return; }
    if (!results.length) {
      var empty = document.createElement("li");
      empty.className = "search-empty";
      empty.textContent = "No recipes match “" + query.trim() + "”";
      list.appendChild(empty);
    }
    results.forEach(function (r) {
      var li = document.createElement("li");
      var a = document.createElement("a");
      a.href = root + r.url;
      a.textContent = r.title;
      var where = document.createElement("span");
      where.textContent = r.cuisine + " · " + r.category;
      a.appendChild(where);
      li.appendChild(a);
      list.appendChild(li);
    });
    list.hidden = false;
  }
  input.addEventListener("input", function () { show(search(input.value), input.value); });
  input.addEventListener("focus", function () { if (input.value) show(search(input.value), input.value); });
  input.addEventListener("keydown", function (e) {
    if (e.key === "ArrowDown") {
      var first = list.querySelector("a");
      if (first) { e.preventDefault(); first.focus(); }
    }
  });
  list.addEventListener("keydown", function (e) {
    var links = [].slice.call(list.querySelectorAll("a"));
    var i = links.indexOf(document.activeElement);
    if (e.key === "ArrowDown" && i < links.length - 1) { e.preventDefault(); links[i + 1].focus(); }
    if (e.key === "ArrowUp") { e.preventDefault(); (i > 0 ? links[i - 1] : input).focus(); }
  });
  input.form.addEventListener("submit", function (e) {
    e.preventDefault();
    var first = list.querySelector("a");
    if (first) window.location.href = first.href;
  });

  // ---- Command palette (Ctrl/Cmd+K) ----
  var palette = null;
  function actions() {
    return [
      { label: "What can I cook?", hint: "Pick what's in the fridge", go: function () { location.href = root + "cook.html"; } },
      { label: "Shopping list", hint: stored("fk-list", []).length + " recipes", go: function () { location.href = root + "list.html"; } },
      { label: "Surprise me", hint: "A random recipe", go: function () { location.href = root + index[Math.floor(Math.random() * index.length)].url; } },
      { label: "Switch light / dark", hint: "Theme", go: toggleTheme },
      { label: "Print the book", hint: "Every recipe, laid out for paper", go: function () { location.href = root + "book.html"; } },
      { label: "Home", hint: "The Field Kitchen", go: function () { location.href = root + "index.html"; } }
    ];
  }
  function openPalette() {
    if (palette) return;
    var opener = document.activeElement;
    palette = document.createElement("div");
    palette.className = "palette";
    palette.setAttribute("role", "dialog");
    palette.setAttribute("aria-modal", "true");
    palette.setAttribute("aria-label", "Command palette");
    palette.innerHTML =
      '<div class="palette-box"><input type="search" placeholder="Search recipes, cuisines or actions" aria-label="Search recipes, cuisines or actions">' +
      '<ul class="palette-list" role="listbox"></ul><p class="palette-foot"><kbd>↑</kbd><kbd>↓</kbd> to move <kbd>Enter</kbd> to open <kbd>Esc</kbd> to close</p></div>';
    document.body.appendChild(palette);
    var field = palette.querySelector("input");
    var ul = palette.querySelector(".palette-list");
    var items = [];
    var active = 0;

    function close() {
      palette.remove(); palette = null;
      if (opener && opener.focus) opener.focus();
    }
    function render() {
      var q = field.value.trim();
      items = [];
      if (!q) {
        stored("fk-recent", []).forEach(function (url) {
          var r = index.filter(function (x) { return x.url === url; })[0];
          if (r) items.push({ group: "Recent", label: r.title, hint: r.cuisine, go: function () { location.href = root + r.url; } });
        });
      } else {
        search(q, 6).forEach(function (r) {
          items.push({ group: "Recipes", label: r.title, hint: r.cuisine + " · " + r.category, go: function () { location.href = root + r.url; } });
        });
        var seen = {};
        index.forEach(function (r) {
          if (!seen[r.cuisine] && fold(r.cuisine).indexOf(fold(q)) !== -1) {
            seen[r.cuisine] = true;
            var slug = r.url.split("/")[0];
            items.push({ group: "Cuisines", label: r.cuisine, hint: "Kitchen", go: function () { location.href = root + slug + "/index.html"; } });
          }
        });
      }
      actions().forEach(function (a) {
        if (!q || fold(a.label).indexOf(fold(q)) !== -1) items.push({ group: "Actions", label: a.label, hint: a.hint, go: a.go });
      });
      active = 0;
      ul.textContent = "";
      var lastGroup = "";
      items.forEach(function (it, i) {
        if (it.group !== lastGroup) {
          var g = document.createElement("li");
          g.className = "palette-group"; g.textContent = it.group; g.setAttribute("role", "presentation");
          ul.appendChild(g); lastGroup = it.group;
        }
        var li = document.createElement("li");
        li.setAttribute("role", "option");
        li.id = "palette-" + i;
        li.innerHTML = "<span></span><small></small>";
        li.firstChild.textContent = it.label;
        li.lastChild.textContent = it.hint || "";
        li.addEventListener("click", function () { var go = it.go; close(); go(); });
        li.addEventListener("mousemove", function () { setActive(i); });
        ul.appendChild(li);
      });
      if (!items.length) {
        var none = document.createElement("li");
        none.className = "palette-empty"; none.textContent = "Nothing found";
        ul.appendChild(none);
      }
      setActive(0);
    }
    function setActive(i) {
      active = i;
      [].forEach.call(ul.querySelectorAll("[role=option]"), function (li) {
        var on = li.id === "palette-" + i;
        li.setAttribute("aria-selected", String(on));
        if (on) li.scrollIntoView({ block: "nearest" });
      });
      field.setAttribute("aria-activedescendant", "palette-" + i);
    }
    field.addEventListener("input", render);
    field.addEventListener("keydown", function (e) {
      if (e.key === "ArrowDown") { e.preventDefault(); setActive(Math.min(active + 1, items.length - 1)); }
      if (e.key === "ArrowUp") { e.preventDefault(); setActive(Math.max(active - 1, 0)); }
      if (e.key === "Enter" && items[active]) { e.preventDefault(); var go = items[active].go; close(); go(); }
      if (e.key === "Escape") { e.preventDefault(); close(); }
    });
    palette.addEventListener("click", function (e) { if (e.target === palette) close(); });
    render();
    field.focus();
  }
  window.FieldKitchenPalette = openPalette;

  // ---- Keyboard ----
  document.addEventListener("keydown", function (e) {
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "k") { e.preventDefault(); openPalette(); return; }
    var typing = /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName);
    if (e.key === "/" && !typing && !palette) {
      e.preventDefault();
      if (getComputedStyle(menuToggle).display !== "none") setMenu(true);
      input.focus();
    }
    if (e.key === "Escape" && !palette) {
      if (document.activeElement === input || list.contains(document.activeElement)) {
        input.value = ""; show([], ""); input.blur();
      }
      setCuisines(false);
      setMenu(false);
    }
  });

  // ---- Filter chips (home and cuisine pages) ----
  [].forEach.call(document.querySelectorAll(".filter-scope"), function (scope) {
    var chips = scope.querySelector(".chips");
    if (!chips) return;
    var buttons = [].slice.call(chips.querySelectorAll(".chip"));
    var menu = chips.querySelector(".style-menu");
    var groups = [].slice.call(scope.querySelectorAll(".filter-group"));
    var empty = scope.querySelector(".filter-empty");
    chips.hidden = false;
    scope.classList.add("js-limited");
    var track = chips.querySelector(".chip-track");
    var checkOverflow = function () { track.classList.toggle("overflows", track.scrollWidth > track.clientWidth + 1); };
    checkOverflow();
    window.addEventListener("resize", checkOverflow);
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(checkOverflow);
    // One filter at a time: a chip clears the style menu, and the style menu clears the chips.
    var toggle = menu && menu.querySelector(".style-toggle");
    var options = menu ? [].slice.call(menu.querySelectorAll("[data-style]")) : [];
    function setMenu(open) {
      menu.classList.toggle("open", open);
      toggle.setAttribute("aria-expanded", String(open));
    }
    function resetStyle() {
      if (!menu) return;
      toggle.firstChild.textContent = "Any style";
      toggle.classList.remove("active");
      options.forEach(function (o) { o.setAttribute("aria-selected", String(o.getAttribute("data-style") === "")); });
    }
    if (menu) {
      toggle.addEventListener("click", function () { setMenu(!menu.classList.contains("open")); });
      options.forEach(function (o) {
        o.addEventListener("click", function () {
          var style = o.getAttribute("data-style");
          setMenu(false);
          if (!style) { buttons[0].click(); return; }
          buttons.forEach(function (x) { x.setAttribute("aria-pressed", "false"); });
          options.forEach(function (x) { x.setAttribute("aria-selected", String(x === o)); });
          toggle.firstChild.textContent = o.firstChild.textContent;
          toggle.classList.add("active");
          apply(style);
        });
      });
      document.addEventListener("click", function (e) { if (!menu.contains(e.target)) setMenu(false); });
      document.addEventListener("keydown", function (e) { if (e.key === "Escape") setMenu(false); });
    }
    buttons.forEach(function (b) {
      b.addEventListener("click", function () {
        var tag = b.getAttribute("data-filter");
        buttons.forEach(function (x) { x.setAttribute("aria-pressed", String(x === b)); });
        resetStyle();
        apply(tag);
      });
    });
    function apply(tag) {
      var shown = 0;
      groups.forEach(function (group) {
        // Cards with data-limit (home page) show only their first few matches.
        var limit = parseInt(group.getAttribute("data-limit"), 10) || Infinity;
        var visible = 0;
        group.querySelectorAll("[data-tags]").forEach(function (item) {
          var match = !tag || item.getAttribute("data-tags").split(" ").indexOf(tag) !== -1;
          item.hidden = !match || visible >= limit;
          if (match) visible++;
        });
        group.hidden = visible === 0;
        shown += visible;
      });
      empty.hidden = shown > 0;
    }
    buttons[0].click();  // apply "All", including any per-card limit
  });

  // ---- Print button on the book page ----
  [].forEach.call(document.querySelectorAll("[data-print]"), function (b) {
    b.addEventListener("click", function () { window.print(); });
  });

  // ---- Fade-up (and icons drawing themselves) as things scroll in ----
  var tiles = document.querySelectorAll(".reveal");
  if (!calm && tiles.length && "IntersectionObserver" in window) {
    document.documentElement.classList.add("reveal-ready");
    var reported = false;
    var seen = new IntersectionObserver(function (entries) {
      reported = true;
      entries.forEach(function (e) {
        if (e.isIntersecting) { e.target.classList.add("in"); seen.unobserve(e.target); }
      });
    }, { rootMargin: "0px 0px -8% 0px" });
    tiles.forEach(function (el) { seen.observe(el); });
    // Never leave the page blank: if the observer hasn't reported, show everything.
    setTimeout(function () {
      if (!reported) tiles.forEach(function (el) { el.classList.add("in"); });
    }, 1000);
  }

  // ---- Cards tilt towards the pointer, with a soft highlight ----
  if (!calm && window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
    [].forEach.call(document.querySelectorAll("[data-tilt]"), function (card) {
      card.addEventListener("pointermove", function (e) {
        var box = card.getBoundingClientRect();
        var x = (e.clientX - box.left) / box.width, y = (e.clientY - box.top) / box.height;
        card.style.transform = "perspective(900px) rotateX(" + ((0.5 - y) * 5).toFixed(2) + "deg) rotateY(" +
          ((x - 0.5) * 6).toFixed(2) + "deg) translateY(-3px)";
        card.style.setProperty("--mx", (x * 100).toFixed(1) + "%");
        card.style.setProperty("--my", (y * 100).toFixed(1) + "%");
      });
      card.addEventListener("pointerleave", function () { card.style.transform = ""; });
    });
  }

  // ---- Offline / install ----
  if ("serviceWorker" in navigator && location.protocol === "https:") {
    navigator.serviceWorker.register(root + "sw.js").catch(function () { /* the site still works online */ });
  }
})();
